// В серверном коде вашего элемента, на этом компьютере: порт даёт узел, ключ у вашего элемента свой
const base = `http://127.0.0.1:${port}`
const headers = { 'content-type': 'application/json', 'X-Element-Key': process.env.ELEMENT_KEY }
// без from: ваш ключ и есть ваше пространство
await fetch(`${base}/v1/remember`, { method: 'POST', headers, body: JSON.stringify({ text: 'такси из аэропорта стоило 40 евро' }) })
const answer = await fetch(`${base}/v1/recall`, { method: 'POST', headers, body: JSON.stringify({ text: 'сколько стоило такси?' }) }).then((r) => r.json())
